import { forwardRef, useImperativeHandle, useRef, useState } from 'react';

interface InputHandle {
  focus: () => void;
  clear: () => void;
}

interface InputProps {
  label: string;
}

const Input = forwardRef<InputHandle, InputProps>(({ label }, ref) => {
  const inputRef = useRef<HTMLInputElement>(null);
  const [value, setValue] = useState('');

  useImperativeHandle(ref, () => ({
    focus() {
      inputRef.current?.focus();
    },
    clear() {
      setValue('');
      inputRef.current?.focus();
    },
  }));

  return (
    <label className="flex flex-col gap-1">
      <span className="text-sm font-medium">{label}</span>
      <input
        ref={inputRef}
        value={value}
        onChange={(e) => setValue(e.target.value)}
        className="rounded border px-3 py-2"
      />
    </label>
  );
});

function Form() {
  const inputRef = useRef<InputHandle>(null);

  return (
    <form>
      <Input ref={inputRef} label="Email" />
      <button type="button" onClick={() => inputRef.current?.focus()}>Focus</button>
      <button type="button" onClick={() => inputRef.current?.clear()}>Clear</button>
    </form>
  );
}

import { forwardRef, useImperativeHandle, useState } from 'react';

interface ModalHandle {
  open: () => void;
  close: () => void;
  isOpen: boolean;
}

const Modal = forwardRef<ModalHandle, { title: string }>(({ title }, ref) => {
  const [isOpen, setIsOpen] = useState(false);

  useImperativeHandle(ref, () => ({
    get isOpen() {
      return isOpen;
    },
    open() {
      setIsOpen(true);
    },
    close() {
      setIsOpen(false);
    },
  }), [isOpen]);

  if (!isOpen) return null;
  return <div className="modal">{title}</div>;
});
